package io.loombus.benchmark;
import io.loombus.Backpressure; import io.loombus.ExecutionMode; import io.loombus.LoomBus; import io.loombus.LoomBusOps;
import java.time.Duration; import java.util.List; import java.util.concurrent.Semaphore; import java.util.stream.IntStream;
/** Baseline comparison harness: CPU, blocking I/O, and scarce downstream resource. */
public final class MultiplexingBenchmark {
 public static void main(String[] args){System.out.println("=== LoomBus vs ParallelStream Multiplexing Benchmark ===");System.out.println("Available processors: "+Runtime.getRuntime().availableProcessors());benchmarkCpuBound();benchmarkBlockingIo();benchmarkScarceDownstreamResource();}
 private static void benchmarkCpuBound(){List<Integer> items=IntStream.range(0,100_000).boxed().toList();System.out.println("\n--- 1. Pure CPU Transform (100,000 items) ---");try(var bus=new LoomBus();var ops=new LoomBusOps(bus)){for(ExecutionMode mode:ExecutionMode.values()){ops.mapAll(mode,items.subList(0,10_000),MultiplexingBenchmark::cpuWork);long start=System.nanoTime();List<Long> out=ops.mapAll(mode,items,MultiplexingBenchmark::cpuWork);long elapsedMs=(System.nanoTime()-start)/1_000_000;System.out.printf("%-16s -> count=%d, elapsed=%d ms%n",mode,out.size(),elapsedMs);}}}
 private static void benchmarkBlockingIo(){List<Integer> items=IntStream.range(0,1_000).boxed().toList();System.out.println("\n--- 2. Blocking I/O Fan-Out (1,000 items @ 15 ms sleep) ---");var defaults=new LoomBusOps.Defaults(2_048,64,Backpressure.WAIT,Duration.ofSeconds(5));try(var bus=new LoomBus();var ops=new LoomBusOps(bus,defaults)){for(ExecutionMode mode:ExecutionMode.values()){long start=System.nanoTime();List<Integer> out=ops.mapAll(mode,items,i->{sleepQuietly(15);return i*2;});long elapsedMs=(System.nanoTime()-start)/1_000_000;System.out.printf("%-16s -> count=%d, elapsed=%d ms%n",mode,out.size(),elapsedMs);}}}
 private static void benchmarkScarceDownstreamResource(){List<Integer> items=IntStream.range(0,500).boxed().toList();System.out.println("\n--- 3. Scarce Downstream Pool (500 items, 16 DB slots @ 10 ms) ---");var defaults=new LoomBusOps.Defaults(1_024,16,Backpressure.WAIT,Duration.ofSeconds(5));try(var bus=new LoomBus();var ops=new LoomBusOps(bus,defaults)){for(ExecutionMode mode:ExecutionMode.values()){Semaphore dbConnections=new Semaphore(16);long start=System.nanoTime();List<Integer> out=ops.mapAll(mode,items,i->{dbConnections.acquireUninterruptibly();try{sleepQuietly(10);return i+1;}finally{dbConnections.release();}});long elapsedMs=(System.nanoTime()-start)/1_000_000;System.out.printf("%-16s -> count=%d, elapsed=%d ms%n",mode,out.size(),elapsedMs);}}}
 private static long cpuWork(int x){long acc=x;for(int i=0;i<200;i++)acc=(acc*31L+i)^(acc>>>3);return acc;}
 private static void sleepQuietly(long millis){try{Thread.sleep(millis);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new RuntimeException(e);}}
}